	// rule that nothing else spells a key prefix, and it reads the source a line at a time.
	function ovKeyFor(group, id) { return (group === 'link' ? 'l:' : group === 'label' ? 't:' : 'n:') + id; }
	function isOverridable(el, prop) { return !!(LPN_OVERRIDABLE[elGroup(el)] || {})[prop]; }
	function inBaseScenario() { return !!activeScenario().isBase; }
	function hasOverride(el, prop) {
		var ov = activeScenario().overrides[ovKey(el)];
		return !!(ov && Object.prototype.hasOwnProperty.call(ov, prop));
	}
	// Base's OWN value for a property, ignoring whatever the active scenario says -- what the
	// popup shows beside an overridden field, and what clearing a marker returns the field to.
	function baseValue(el, prop) {
		if (prop === 'active' && el['_' + prop] === undefined) { return true; }
		return el['_' + prop];
	}
	function setOverride(el, prop, value) {
		if (!el || !isOverridable(el, prop) || inBaseScenario()) { return; }
		var scn = activeScenario(), key = ovKey(el);
		if (!scn.overrides[key]) { scn.overrides[key] = {}; }
		// UNDEFINED BECOMES NULL. In Base `undefined` says "no head typed"; in an override map
		// absence means "inherit Base", so a blank-capable field stored as undefined says "inherit"
		// rather than "deliberately blank" -- and JSON.stringify DROPS an undefined value, so the
		// override evaporates on the next save, undo snapshot or file write. At the SEAM rather than
		// the call site, so every future blank-capable field is covered without anyone remembering.
		scn.overrides[key][prop] = (value === undefined) ? null : value;
	}
	function clearOverride(el, prop) {
		var scn = activeScenario(), key = ovKey(el), ov = scn.overrides[key];
		if (!ov) { return; }
		delete ov[prop];
		// An empty map is dropped rather than left behind: an element with an empty object still in
		// the map reads as "this element is touched here", the claim the marker exists to make.
		if (!Object.keys(ov).length) { delete scn.overrides[key]; }
	}
	// THE ONE WRITE SEAM every property editor goes through. In Base it writes the element (which
	// IS the propagation -- there is no push upward in the delta model); in a scenario it records
	// an override. A call site that writes `el._diameter` directly is therefore not merely
	// impolite: inside a scenario it silently edits Base under every other scenario at once.
	function setProp(el, prop, value) {
		if (!inBaseScenario() && isOverridable(el, prop)) { setOverride(el, prop, value); return; }
		el['_' + prop] = value;
	}
	function overrideCount(scn) {
		var total = 0;
		Object.keys(scn.overrides || {}).forEach(function (key) { total += Object.keys(scn.overrides[key]).length; });
		// **A DEMAND MULTIPLIER COUNTS AS ONE**, though it is not an element override and lives
		// nowhere near `overrides`. This number is what the scenario menu shows beside a name, and
		// it is read as "how much does this scenario change" -- a max-day scenario whose whole
		// content is a 1.8 would otherwise say (0) and read as an empty scenario nobody finished.
		// **AND ONLY WHEN IT DIFFERS FROM THE DOCUMENT'S OWN.** Since a new scenario is seeded with
		// the project's multiplier, counting the mere presence of the field would badge every
		// freshly created scenario (1) before anybody had changed anything -- the opposite of the
		// misreading the count exists to prevent.
		if (typeof scn.demandMultiplier === 'number' && isFinite(scn.demandMultiplier)
			&& scn.demandMultiplier !== (settings.hydraulics || {}).demandMultiplier) { total += 1; }
		return total;
	}
	// Every scenario's overrides on one element -- what a Base-side deletion is about to destroy,
	// counted before the confirm rather than after it.
	// TAKES A KEY, not an id: only the caller knows whether it holds a node or a link (Task 324), and
	// a bare id counts -- and purges -- whichever of the pair the map happened to have.

	function overrideCountForElement(key) {
		var total = 0;
		scenarios.forEach(function (s) {
			if (s.isBase || !s.overrides[key]) { return; }
			total += Object.keys(s.overrides[key]).length;
		});
		return total;
	}
	function purgeOverrides(key) {
		scenarios.forEach(function (s) { delete s.overrides[key]; });
	}

	// ---- the scenario selector, and its "what am I working on right now" readout ----
	// The count is only cheap to compute because a scenario IS its overrides -- there is no second
	// document to diff against.
	function scenarioDisplayName(s) {
		var pc = EngCalcs.pageConfig || {};
		// Base's stored name is the language-free literal 'Base' (defaultScenarios()); the word on
		// screen comes from the lang file, so a user's data never carries an English word.
		return s.isBase ? (pc.lpn_scenario_base || 'Base') : (s.name || '');
	}
	function refreshScenarioStatus() {
		var btn = document.getElementById('lpn_scenario_btn'), pc = EngCalcs.pageConfig || {};
		if (!btn) { return; }
		var scn = activeScenario();
		// Same "Label: value | Label: value" shape as the units readout beside it (refreshMapStatus),
		// and no plural agreement anywhere -- "Overrides: 1" needs no rule in any of the 27 languages.
		//
		// Through setLabel(), so this control carries its icon the way every other menu opener on the
		// page does (ROADMAP Task 499.01) -- one plan sheet branching into three, drawn once in
		// lib/Icons.lib.php. It rebuilds the whole content, which is why the icon has to be re-applied
		// on every refresh rather than set once in wireScenarioButton(): the text changes on every
		// scenario switch and on every override, and a plain textContent assignment would wipe it.
		setLabel(btn, 'scenarios',
			(pc.lpn_scenario_label || 'Scenario') + ': ' + scenarioDisplayName(scn)
			+ ' | ' + (pc.lpn_scenario_overrides || 'Overrides') + ': ' + overrideCount(scn));
		refreshScenarioTip(btn);
		// The scenario name is user-typed and can be long, so the bottom band's width is not knowable
		// in advance -- a bottom legend re-dodges around whatever it now measures.
		placeLegends();
	}
	// **THE COUNT HAS TO SAY WHAT IT IS COUNTING** (ROADMAP Task 512). "Custom values: 3" and three
	// amber rings on the map are the same fact, and nothing said so: Tom and Mary each read the rings
	// as a stuck highlight without connecting them to the readout sitting under them. So the second
	// sentence appears only when the count is above zero -- with no overrides there are no rings to
	// explain, and a permanent sentence about a mark that is not on screen is noise.
	function refreshScenarioTip(btn) {
		var pc = EngCalcs.pageConfig || {}, tip = pc.lpn_scenario_tip || '';
		if (!btn || !tip) { return; }
		if (overrideCount(activeScenario()) > 0 && pc.lpn_scenario_overrides_tip) {
			// The base scenario's NAME comes from its own key, never spelled again here: embedded
			// as a bare word it was translated a second time and named no control. Task 573.
			tip += ' ' + pc.lpn_scenario_overrides_tip
				.replace(/\{base\}/g, pc.lpn_scenario_base || 'Base');
		}
		btn.title = tip;
	}
	// Everything a scenario can change at once: which values the solve reads, which links are
	// dashed, which elements are greyed out, which carry a halo, and what an open popup shows.
	// A full rebuild rather than a targeted refresh, because a scenario switch can change every
	// element on the map and the cost is one buildDom on a network of a few hundred elements.
	function applyScenarioChange() {
		closePopup();
		buildDom();
		refreshSymbolSizes();
		refreshValueColors();
		refreshScenarioStatus();
		// **THE SETTINGS BOX IS A NON-GREEDY BOX AND MAY BE OPEN RIGHT NOW.** Since the demand
		// multiplier row reads a different home in Base and in a scenario, a switch made while it is
		// open would leave that field showing the number belonging to the scenario you just left --
		// and the next keystroke would write it into the wrong place.
		rebuildSettingsBox();
		scheduleSolve();
		saveToStorage();
	}
	function switchScenario(id) {
		if (project.activeScenario === id) { return; }
		project.activeScenario = id;
		applyScenarioChange();
	}
	function newScenarioId() {
		var n = 1, used = {};
		scenarios.forEach(function (s) { used[s.id] = true; });
		while (used['s' + n]) { n++; }
		return 's' + n;
	}
	// **A NEW SCENARIO IS BORN WITH THE DEMAND MULTIPLIER THE PROJECT ALREADY HAS** (Tom,
	// 2026-09-02: *"Creating a Scenario blanks the demand multiplier. It should preserve it until
	// you change it as with all other settings."*). Every other row in Settings > Hydraulics reads
	// the document in Base and in a scenario alike, so only this one -- the single per-scenario
	// option -- went blank on the way in, and a blank box beside nine filled ones reads as a
	// setting that was lost rather than one that is inherited.
	//
	// **SEEDED, NOT DISPLAYED-AS-INHERITED.** Drawing the document's number in an empty box is the
	// placeholder Tom struck on 2026-09-01: a number in the box is a number in the document, and
	// nothing else. So the value is really written onto the scenario, which is also what makes it
	// survive a save and a reopen unchanged.
	//
	// A document that states no multiplier seeds nothing, so Base blank stays scenario blank; and
	// the seed comes from the DOCUMENT rather than from whichever scenario happened to be active,
	// because a new scenario copies no overrides from its predecessor either.
	function createScenario(name) {
		var s = { id: newScenarioId(), name: name, overrides: {} },
			dm = (settings.hydraulics || {}).demandMultiplier;
		if (typeof dm === 'number' && isFinite(dm)) { s.demandMultiplier = dm; }
		scenarios.push(s);
		project.activeScenario = s.id;
		applyScenarioChange();
		return s;
	}
	function deleteScenario(id) {
		var s = scenarioById(id);
		if (!s || s.isBase) { return; }
		scenarios = scenarios.filter(function (x) { return x.id !== id; });
		if (project.activeScenario === id) { project.activeScenario = baseScenario().id; }
		applyScenarioChange();
	}
	function scenarioById(id) {
		for (var i = 0; i < scenarios.length; i++) { if (scenarios[i].id === id) { return scenarios[i]; } }
		return null;
	}
	/**
	 * The scenario rows, built and returned rather than opened.
	 *
	 * **SPLIT OUT 2026-09-02 so the Water menu can hang them as a FLY-OUT.** Tom: *"Scenarios: It's
	 * a submenu, so it needs flyout placement and arrow like others here and everywhere. Instead, it
	 * replaces the Water menu."* It did -- the row called openScenarioMenu() with the Water button's
	 * own anchor, which reopens the SAME popup with different rows, so the pull-down the user was
	 * reading was overwritten in place. A row that leads somewhere is a submenu, and this file
	 * already has submenus with an arrow and a fly-out; Scenarios simply was not one.
	 *
	 * Both doors read this one list -- the fly-out and the map's bottom status strip -- so the two
	 * cannot drift.
	 */
	function scenarioMenuRows() {
		var pc = EngCalcs.pageConfig || {}, rows = [], scn = activeScenario();
		scenarios.forEach(function (s) {
			rows.push({
				// A tick on the row you are already in, the way every view menu in this file's
				// neighbourhood marks a current choice. No icon column entry, so the marker cannot
				// be mistaken for a command's glyph.
				label: (s.id === scn.id ? '✓ ' : '  ') + scenarioDisplayName(s)
					+ (s.isBase ? '' : ' (' + overrideCount(s) + ')'),
				fn: function () { switchScenario(s.id); }
			});
		});
		rows.push({ separator: true });
		rows.push({
			icon: 'insert', label: pc.lpn_scenario_new || 'New scenario…',
			fn: function () {
				var suggested = (pc.lpn_scenario_new_name || 'Scenario {n}').replace('{n}', scenarios.length);
				var v = window.prompt(pc.lpn_scenario_prompt_name || 'Name for this scenario', suggested);
				if (v === null) { return; }
				v = v.trim();
				if (!v) { return; }
				saveUndoSnapshot();
				createScenario(v);
			}
		});
		rows.push({
			// Base cannot be renamed away: its name is not stored in the user's language and the
			// selector keys off isBase, so a rename here would rename nothing a user can see.
			icon: 'edit', label: pc.lpn_scenario_rename || 'Rename scenario…', disabled: scn.isBase,
			fn: function () {
				var v = window.prompt(pc.lpn_scenario_prompt_name || 'Name for this scenario', scn.name || '');
				if (v === null || !v.trim()) { return; }
				saveUndoSnapshot();
				scn.name = v.trim();
				refreshScenarioStatus();
				saveToStorage();
			}
		});
		rows.push({
			icon: 'close', label: pc.lpn_scenario_delete || 'Delete scenario', disabled: scn.isBase,
			fn: function () {
				// The count is the whole of the warning: a scenario holding nothing is worth no
				// question, and one holding forty values is worth a specific one.
				var msg = (pc.lpn_scenario_delete_confirm || 'Delete the scenario {name}, and the {n} values it holds? The drawing itself is not changed.')
					.replace('{name}', scenarioDisplayName(scn)).replace('{n}', overrideCount(scn));
				if (!window.confirm(msg)) { return; }
				saveUndoSnapshot();
				deleteScenario(scn.id);
			}
		});
		rows.push({ separator: true });
		rows.push({
			label: pc.lpn_scenario_push_btn || 'Apply Base values to all scenarios',
			tip: pc.lpn_scenario_push_tip,
			// BASE-LEVEL ONLY, and disabled rather than hidden so the vocabulary stays learnable
			// (the menu convention this file already follows). Run from inside a scenario the
			// action has no meaning: it pushes Base's values outward, and Base is not where you
			// are standing.
			disabled: !scn.isBase || scenarios.length < 2,
			// Wrapped, NOT passed by reference: pushBaseToScenarios() now takes an element to scope
			// itself to, and openMenu() calling fn(anything) would silently turn the all-elements
			// push into a push against whatever it happened to hand over.
			fn: function () { pushBaseToScenarios(); }
		});
		return rows;
	}
	function openScenarioMenu(anchor) { openMenu(anchor, scenarioMenuRows()); }
	// THE SELECTOR AND THE READOUT ARE ONE CONTROL, in the map's bottom status strip beside the
	// units -- where this page already answers continuous questions about the state of the map.
	function wireScenarioButton() {
		var btn = document.getElementById('lpn_scenario_btn');
		if (!btn) { return; }
		var pc = EngCalcs.pageConfig || {};
		if (pc.lpn_scenario_tip) { btn.className += ' ec-help'; }
		refreshScenarioTip(btn);
		// stopPropagation for the same reason every other menu opener in this file does it: the
		// document-level dismissal in wireTabs() would otherwise close the menu this click opens.
		btn.addEventListener('click', function (e) { e.stopPropagation(); openScenarioMenu(e.currentTarget); });
		refreshScenarioStatus();
	}

	// The property list BOTH pushes share -- the Settings panel's "apply starting values to every
	// element" and the scenario menu's "apply Base values to every scenario". Shared, not copied:
	// the two must agree about which properties exist, which elements carry them, and what each is
	// called.
	// `applies` is what keeps a push physical rather than blindly per-field: a reservoir has no
	// demand, and a pump has no diameter/roughness/km, so neither is counted or touched.
	function pushSpecList() {
		var pc = EngCalcs.pageConfig || {};
		return [
			{ key: 'nodeElev', group: 'node', field: 'elev', label: pc.lpn_field_elev || 'Elevation',
				// Elevation is survey data, not an overridable design variable (LPN_OVERRIDABLE), so
				// it has no `prop` and the scenario push skips it. It stays in the Settings push,
				// which writes Base.
				applies: function () { return true; }, get: function (n) { return n.elev; }, set: function (n, v) { n.elev = v; } },
			// `altField` exists for this one row and says why it has to: a push is scoped by the
			// labels on screen, and since 2026-08-25 a map showing a junction's demand is normally
			// showing the RESOLVED one. Both labels describe the same stored number, so either being
			// on means the user can see what a push would change.
			//
			// **AND A JUNCTION WHOSE DEMAND IS A LIST IS NOT PUSHABLE** (Task 468). Both callers --
			// the Settings push and Find and Replace -- write ONE number, and one number cannot state
			// a breakdown: writing it would set the first category and leave the rest standing, so
			// the junction would quietly draw the default PLUS its other categories. Excluded here
			// rather than in either caller, which is also what keeps it out of their counts.
			{ key: 'demand', group: 'node', field: 'demand', altField: 'demandActual', prop: 'demand', label: pc.lpn_field_base_demand || 'Base demand',
				applies: function (n) { return !isFixedHeadNode(n) && !(n.extraDemands && n.extraDemands.length); }, get: function (n) { return effective(n, 'demand'); }, set: function (n, v) { n._demand = v; } },   // base-write: pushSpecList: the documented Base-level push, refused outside Base
			// **FIND AND REPLACE'S REASON FOR BEING HERE, NOT A STARTING VALUE'S** (Task 530). This
			// list answers three questions, and a required fire flow answers two of them: what it is
			// called and how it is written. It has no row in Settings > Starting values and no map
			// label, so pushFieldShown() is false for it and BOTH pushes skip it -- a junction is
			// given a fire flow because of what stands on it, which is not a thing to seed from a
			// default or to force onto every scenario at once.
			{ key: 'fireFlow', group: 'node', field: 'fireFlow', prop: 'fireFlow', label: pc.lpn_ff_required || 'Required fire flow',
				applies: function (n) { return n.type === 'junction'; }, get: function (n) { return fireFlowOwn(n); }, set: function (n, v) { n._fireFlow = fireFlowStore(v); } },   // base-write: pushSpecList: the documented Base-level push, refused outside Base
			{ key: 'diameter', group: 'link', field: 'diameter', prop: 'diameter', label: pc.lpn_field_diameter || 'Diameter',
				applies: function (l) { return l.type !== 'pump'; }, get: function (l) { return effective(l, 'diameter'); }, set: function (l, v) { l._diameter = v; } },   // base-write: pushSpecList: the documented Base-level push, refused outside Base
			// PIPE-ONLY, not merely not-a-pump: a valve is a zero-length link, so no friction formula
			// ever reads its roughness, and a default for it would be a control with no effect.
			{ key: 'roughness', group: 'link', field: 'roughness', prop: 'roughness', label: roughnessLabel(),
				applies: function (l) { return l.type === 'pipe'; }, get: function (l) { return effective(l, 'roughness'); }, set: function (l, v) { l._roughness = v; } },   // base-write: pushSpecList: the documented Base-level push, refused outside Base
			{ key: 'k', group: 'link', field: 'km', prop: 'k', label: pc.lpn_field_km || 'Minor (local) loss coefficient, k',
				applies: function (l) { return l.type !== 'pump'; }, get: function (l) { return effective(l, 'k'); }, set: function (l, v) { l._k = v; } },   // base-write: pushSpecList: the documented Base-level push, refused outside Base
			// **THE TWO REACTION COEFFICIENTS, HERE FOR FIND AND REPLACE'S REASON** (Task 566) --
			// the same standing a required fire flow has in this list. Neither has a row in
			// Settings > Starting values and neither has a map label, so pushFieldShown() is false
			// for both and BOTH pushes skip them: relining a run of mains is a fact about those
			// mains, not a default to seed from or to force onto every scenario at once. What this
			// list is being asked for here is what the property is called, which pipes carry it,
			// and how it is written -- and replaceWrite() takes `prop` and goes through setProp().
			//
			// PIPE-ONLY, and only while a chemical is tracked: `applies` is what keeps a Replace
			// physical, and a valve is a zero-length link that no reaction is computed along.
			{ key: 'bulkCoeff', group: 'link', field: 'bulkCoeff', prop: 'bulkCoeff', label: pc.lpn_reaction_bulk || 'Bulk reaction coefficient',
				applies: function (l) { return l.type === 'pipe' && reactionFieldsShown(); }, get: function (l) { return effective(l, 'bulkCoeff'); }, set: function (l, v) { l._bulkCoeff = v; } },   // base-write: pushSpecList: the documented Base-level push, refused outside Base
			{ key: 'wallCoeff', group: 'link', field: 'wallCoeff', prop: 'wallCoeff', label: pc.lpn_reaction_wall || 'Wall reaction coefficient',
				applies: function (l) { return l.type === 'pipe' && reactionFieldsShown(); }, get: function (l) { return effective(l, 'wallCoeff'); }, set: function (l, v) { l._wallCoeff = v; } }   // base-write: pushSpecList: the documented Base-level push, refused outside Base
		];
	}
	// Is this push spec's property visible on the map right now? The one place that question is
	// asked, so the Settings push and the scenario push cannot come to different answers about the
	// same checkbox -- and the one place `altField` is honoured.
	function pushFieldShown(s) {
		return !!(labelSettings[s.group][s.field] || (s.altField && labelSettings[s.group][s.altField]));
	}
	// **THE DANGEROUS ACTION** (Task 184). Base-side, it forces the displayed properties onto every
	// scenario, ignoring their markers. In the delta model "forcing Base's value onto a scenario" IS
	// clearing that scenario's override, so the value follows Base and no stale marker claims an
	// intent the user has overruled. Writing Base's number in as a fresh override would pin every
	// scenario permanently to today's Base value, the opposite of what a push is for.
	//
	// SCOPED BY THE DISPLAYED LABELS, the same filter the Settings push uses: the Labels panel is
	// already a per-property checkbox list and already on screen, so the user's own current view
	// defines the blast radius and this needs no property picker.
	// `only` (Task 317) narrows the same action to ONE element -- a parameter rather than a second
	// function, because the counting, the naming, the warning and the undo snapshot are already
	// here and a fork of them drifts silently. The element-scoped push is the SAFE and COMMON case,
	// which is why it lives in the element's own popup while the all-elements version stays in the
	// scenario menu where it is deliberately harder to reach.
	function pushBaseToScenarios(only) {
		var pc = EngCalcs.pageConfig || {};
		if (!inBaseScenario()) { return; }
		var key = only ? ovKey(only) : null, group = only ? elGroup(only) : null;
		// Scoped to ONE element, the other group's properties are nonsense: a node has no diameter,
		// so counting one produces a confirm naming properties this element cannot hold.
		var active = pushSpecList().filter(function (s) {
			return s.prop && pushFieldShown(s) && (!group || s.group === group);
		});
		if (!active.length) {
			alert(pc.lpn_push_none_displayed || 'No default input is showing as a label right now, so there is nothing to apply. Turn on the labels for the properties you want in the Labels panel, then try again.');
			return;
		}
		// Counted, not estimated: how many overrides would actually be discarded. Zero says so in
		// its own words, because "nothing to push" and "pushed nothing" look identical afterwards.
		var hits = 0, touched = 0;
		// The one place the scope is applied, to both the count and the delete -- so a confirm can
		// never promise a different blast radius from the one that happens.
		function scopedKeys(s) { return key ? (s.overrides[key] ? [key] : []) : Object.keys(s.overrides); }
		scenarios.forEach(function (s) {
			if (s.isBase) { return; }
			var any = false;
			// Walks the map by KEY and matches on the property NAME only -- deliberately group-blind,
			// because no property in pushSpecList() exists on both groups (`active` is the only name
			// LPN_OVERRIDABLE shares, and it is not pushable). Task 324.
			scopedKeys(s).forEach(function (k) {
				active.forEach(function (spec) {
					if (Object.prototype.hasOwnProperty.call(s.overrides[k], spec.prop)) { hits++; any = true; }
				});
			});
			if (any) { touched++; }
		});
		if (!hits) { alert(pc.lpn_scenario_push_none || 'No scenario has its own value for any of these properties, so nothing would change.'); return; }
		// NAMES the properties as well as counting them, and NAMES THE ELEMENT when scoped to one --
		// reusing lpn_field_id ("ID") rather than minting a key, per the whole-label reuse rule.
		var msg = (pc.lpn_scenario_push_confirm || 'Make every scenario use the Base values for these properties? Values those scenarios hold of their own are discarded. You can undo this.')
			+ (only ? '\n\n' + (pc.lpn_field_id || 'ID') + ': ' + only.id : '')
			+ '\n\n' + (pc.lpn_push_properties || 'Properties:') + ' ' + active.map(function (s) { return s.label; }).join(', ')
			+ '\n' + (pc.lpn_scenario_push_scenarios || 'Scenarios:') + ' ' + touched
			+ '\n' + (pc.lpn_scenario_push_values || 'Values discarded:') + ' ' + hits;
		if (!window.confirm(msg)) { return; }
		saveUndoSnapshot();
		scenarios.forEach(function (s) {
			if (s.isBase) { return; }
			scopedKeys(s).forEach(function (k) {
				active.forEach(function (spec) { delete s.overrides[k][spec.prop]; });
				if (!Object.keys(s.overrides[k]).length) { delete s.overrides[k]; }
			});
		});
		applyScenarioChange();
	}

	// Map label toggles -- a VIEW preference, not network content, so it is deliberately NOT part of
	// the undo-snapshotted `doc` and is untouched by clearNetwork()/undo().
	function defaultLabelSettings() {
		return {
			// **DEMAND ON, BASE DEMAND OFF** (Tom, 2026-08-25). The map's job is to be readable
			// against itself: the number beside a junction should be the one the pipes into it add
			// up to, and on a patterned network the base is not that number. Both remain one tick
			// away. A project saved before this existed carries `demand: true` and keeps showing
			// exactly the number it always showed -- now under the honest heading -- because the
			// boolean maps are merged key by key and nothing reinterprets a stored toggle.
			// **BASE DEMAND STAYS THE DEFAULT, AND DEMAND IS THE ONE TICK AWAY** (Tom, 2026-08-26).
			// A previous pass flipped this to show the resolved Demand by default, reasoning that a
			// fresh map should show the number the pipes add up to. He reversed it: *"no options, no
			// demand: true. It's just showing Base Demand as user requested (without sufficient
			// advice) in Settings."* The bug was never the CHOICE, it was the LABEL — a base demand
			// printed under the word "Demand". Relabelled, the default is honest, every project that
			// ever existed keeps showing the number it always showed, and nobody's map changes under
			// them for a reason they did not ask for.
			node: { id: true, elev: true, demand: true, demandActual: false, head: false, pressure: true,
				// OFF, like every other field a network does not have until it is asked for.
				quality: false },
			// Every INPUT property a link carries is offered, not just the ones a result depends on:
			// roughness and the minor-loss coefficient are typed per pipe and are exactly the numbers
			// you want spread across a drawing when checking someone's model. Off by default --
			// turning every one on would bury the results.

			link: { id: true, diameter: false, length: false, roughness: false, km: false, flow: true, velocity: true, headloss: false, gradient: false },
			// Per-field decimal places (Task 189). A PARALLEL map, not a boolean-turned-object: the
			// boolean maps are merged key-by-key out of localStorage, and a shape change there
			// silently reinterprets every already-saved network's toggles. Non-numeric fields (ID)
			// have no entry. Three fields depart from the default 2, each for a reason about the
			// QUANTITY:
			//   roughness 0 -- a Hazen-Williams C-factor is a dimensionless integer: 100, 130, 140.
			//     **THE SHIPPED 0 IS THE HAZEN-WILLIAMS CASE ONLY.** The method is selectable
			//     (Task 271) and a Manning n or a Darcy-Weisbach e printed as "0" at 0 places, so
			//     syncRoughnessLabelDecimals() raises this entry whenever the method or the
			//     roughness unit leaves it unable to show the number. Every other entry here is a
			//     constant and this one is a starting value.
			//   diameter 0 -- inches and millimetres are both whole-number standards in this trade.
			//   gradient 4 -- the only field whose unit family offers two forms differing by 100x
			//     (gradePercent and plain rise/run). 2 decimals is useless as a ratio, where a typical
			//     pipe gradient is 0.0043; 4 covers both.

			decimals: {
				// quality 1 -- a water age in hours reads as a whole number and a first decimal
				// ("14.3 hr"); two would be a minute and a half of false precision on a quantity
				// whose own transport step is five minutes. A source share in percent is the same
				// shape of number.
				node: { demand: 2, demandActual: 2, head: 2, pressure: 2, elev: 2, quality: 1 },
				link: { diameter: 0, length: 2, roughness: 0, km: 2, flow: 2, velocity: 2, headloss: 2, gradient: 4 }
			},
			// Per-field PREFIX and SUFFIX text (Task 333), plus one blanket separator between either
			// of them and the number.
			//
			// EMPTY IS NOT THE SAME AS UNSET, which is why these maps ship EMPTY rather than
			// pre-filled. A field with no entry uses labelDefaultPrefix(), which is allowed to be
			// dynamic -- roughness prints C, n or e depending on the friction method selected, and a
			// stored 'C' could not follow that. So: undefined -> ask the default; '' -> print nothing.
			//
			// The separator is blanket and goes BETWEEN VALUES on a one-line label ('Q=120 V=3.1').
			// A prefix's own punctuation is part of the prefix string, so the defaults carry '='.

			prefix: { node: {}, link: {} },
			suffix: { node: {}, link: {} },
			separator: ' ',
			// **LABEL PRIORITY -- WHICH IS NOT A WEIGHT** (Task 397; dev/label-placement-goals.md
			// §2.2, §3.1). ESRI Maplex keeps three numbers apart: LABEL PRIORITY is the order labels
			// are ATTEMPTED in, LABEL WEIGHT is how much a placed label resists being pushed out, and
			// FEATURE WEIGHT is how much a map feature resists being COVERED. Collide.GOAL_WEIGHT is a
			// feature-weight table and only that. This is the first number. Do not merge them.
			//
			// **THE NUMBER IS A DROP ORDER: 1 IS THE FIRST TO GO** (Task 445, Tom 2026-08-19: "our
			// labels priority paradigm really wants to be Labels.Drop First In Case of Conflict").
			// It read the other way round until then -- 1 kept longest -- so a document written
			// before the change is INVERTED by the v8 -> v9 migration, never reinterpreted in place.
			//
			// **ONE COLUMN, TWO AXES, ON PURPOSE.** Both read "lower means this field is given up
			// sooner", but a LINK number orders ROWS INSIDE one label (a label that will not fit
			// sheds from the bottom of the column) while a NODE number orders the TESTS that decide
			// which whole label gives up a contested spot -- the lowest-numbered test is consulted
			// last, so it is the first to stop mattering.
			//
			// **THE ORDER IS THE USER'S. THE DIRECTION IS NOT** -- LPN_NODE_DROP_RULE is that compiled
			// table. A per-row max/min/least-extreme picker was declined: four controls per row that a
			// user must reason through to arrive back at the only sensible setting.
			//
			// PARALLEL to decimals/prefix/suffix rather than nested into the boolean maps, for the
			// reason the decimals comment gives.
			//
			// Link order puts the flow highest so it survives longest. **`id` IS RANK 1 AND SHEDS
			// FIRST**, not the top rank never-shed: a link label lies ALONG its own pipe, so the
			// drawing already says which pipe the numbers belong to and the ID is the one value whose
			// job the label's own position is doing. That argument does NOT carry to node labels,
			// which is why no node ID rank exists.
			priority: {
				// Demand outranks Base demand: on a crowded drawing the resolved number is the one
				// worth the last space, and the base is recoverable from it and the pattern.
				// **QUALITY OUTRANKS EVERYTHING AND SHEDS LAST**, because unlike the five below it is
				// never on unless somebody switched the analysis on and re-ran: a field a user asked for
				// by name is the last one to give up its space. It carries a rank and NO entry in
				// LPN_NODE_DROP_RULE, which is the pair of statements "order this row inside the column"
				// and "do not make this a criterion for which whole label wins a contested spot".
				node: { quality: 6, demandActual: 5, demand: 4, pressure: 3, elev: 2, head: 1 },
				link: { flow: 9, velocity: 8, headloss: 7, gradient: 6,
					diameter: 5, length: 4, roughness: 3, km: 2, id: 1 }
			},
			// Whether a label's network-wide highest/lowest value gets its tick mark (Task 190).
			// Global, not per field. Here rather than in `settings` because a label mark is a property
			// of a label -- and, like the rest of labelSettings, a view preference kept out of `doc`.
			markExtrema: true
		};
	}
	var labelSettings = defaultLabelSettings();
	// The roughness decimal places syncRoughnessLabelDecimals() last computed. See it for why.
	var roughnessDecimalsAuto = 0;

	// **THE SMALL-SCREEN VIEWPORT, ASKED AT THE ONE BREAKPOINT THE PHONE PASS ALREADY USES**
	// (640px, Task 486 -- see the block in css/engcalcs.css that explains why there is exactly one).
	// The literal is repeated here rather than published from CSS because a media query is the only
	// thing that can answer "is a rule firing"; dev/lpn-spike/small-screen-harness.js asserts that
	// this number and the stylesheet's are the same number, so the two cannot drift.
	// It is a VIEWPORT question, never a user-agent one, for the reason that block gives.
	function smallScreen() {
		try { return !!(window.matchMedia && window.matchMedia('(max-width: 640px)').matches); }
		catch (e) { return false; }
	}

	// Gear/settings panel -- like labelSettings, a VIEW/preference object, not network content:
	// persisted to localStorage as a sibling key, deliberately NOT part of the undo-snapshotted
	// `doc`, and untouched by clearNetwork() ("New" clears the network, not your preferences).
	function defaultSettings() {
		return {
			// Keyed by the same structural letters nextId already uses (LPN_ID_KEY) -- changing a
			// prefix only affects IDs generated AFTER the change; existing element IDs are never
			// live-renamed by a settings edit.
			idPrefixes: { J: 'J', R: 'R', T: 'T', L: 'L', P: 'P', V: 'V', X: 'X' },
			// Matches js/lpn-solver.js's own default -- see assembleModel(). No UI edits this:
			// nothing can create an emitter yet, so the control was a no-op (Task 191).
			emitterExponent: 0.5,
			// **EPANET'S OTHER [OPTIONS], SPARSE** (Task 553). A key is present only where a file
			// stated it or a person typed it, so absent means EPANET's own default and the exporter
			// writes nothing -- the same rule `defaultPattern` has always followed. `settings` is
			// serialized WITH the project, so this round-trips without a line anywhere else.
			hydraulics: {},
			// **THE THREE WATER-QUALITY `[OPTIONS]`, AS THE FILE'S OWN TEXT** -- Quality,
			// Diffusivity and Tolerance. Sparse exactly as `hydraulics` is, and STRINGS rather than
			// numbers: nothing here solves with them, so they are carried and written back
			// verbatim, which is the only form `Diffusivity 1.0` and `Quality Trace Lake` both
			// survive. No control, on the emitter-exponent precedent.
			qualityOptions: {},
			// **THE ONE WATER-QUALITY OPTION THAT IS A LIVE INPUT** (water age, source share). The
			// three above stay carried text; this is the interpretation of the first of them, kept
			// BESIDE the token rather than on top of it so an untouched file exports the characters
			// it came in with -- js/lpn-inp.js's lpnQualityParse/lpnQualityText own that rule and
			// `src` is the token it was read from. `mode` is one of none/age/trace/chemical, and
			// 'chemical' means CARRIED, NOT WORKED OUT: this page has no reaction coefficients, so
			// naming a chemical is a fact about the file and never an analysis we ran.
			quality: { mode: 'none', traceNode: '' },
			// **THE TWO `[OPTIONS]` KEYS THAT NAME A FILE BESIDE THE `.inp`** -- `Map` and
			// `Hydraulics USE/SAVE`. Carried text, no control, sparse like the rest: this page
			// cannot open either file and does not act on either line, and reading past them was
			// deleting a line the source stated on every save.
			fileOptions: {},
			// **`tolerance` IS DEPRECATED AND IS NO LONGER SEEDED HERE** (2026-08-28). EPANET's
			// `Accuracy` replaced it; solveAccuracy() still READS it so a project saved before the
			// change keeps its own number, but a new project no longer carries the field at all.
			// 'native' (js/lpn-solver.js) or 'epanet' (the real EPANET engine as WASM,
			// js/lpn-epanet.js). The two agree to 1e-5..1e-3 m of head
			// (dev/lpn-spike/validate_epanet.js).
			//
			// NATIVE IS THE DEFAULT, BUT NOT BECAUSE IT IS FASTER -- it is not.
			// dev/lpn-spike/engine-bench.js: EPANET's own solve is ~0.05 ms at this page's target and
			// ~0.78 ms at 201 nodes, where ours is 0.43 ms and 36 ms. EPANET wins at every size, by
			// more as the network grows.
			//
			// The real and only cost of EPANET is the ONE-TIME 663 KB module load, a genuine cost on
			// a slow connection and why the default has not moved. See Task 313 -- the per-solve gap
			// that remains is our own .inp round trip, not the engine.
			engine: 'native',
			// **AUTOMATIC RECALCULATION, AS A STATED PREFERENCE** (ROADMAP Task 467). Tom,
			// 2026-08-20: *"a toggle under Calculation.Hydraulics for 'Recalculate the simulation
			// for this project automatically.' If it's on, we do our debounce and calculate, and we
			// hide the Calculate button."*
			//
			// **DEFAULT ON, because ON is what the page already did.** The measured heuristic it
			// replaces (EC.LPN_TIME_AUTO) allowed an automatic run on every network that ran inside
			// its budget, which is every ordinary one -- so defaulting OFF would take working
			// behaviour away from everybody to protect the few. The few are protected by the advice
			// instead: a run that measures over EC.LPN_TIME_SLOW_MS says so and names the switch.
			//
			// It is a PROJECT setting, not a browser one, for the reason units are (see "there are
			// no browser units, only PROJECT units"): a big network and a small one want different
			// answers, and the answer belongs to the network. It serializes for free -- the whole
			// `settings` object goes into serializeProject().
			autoRun: true,
			// Default input values for NEWLY created elements -- a mode the user re-enters mid-draw
			// ("OK, now all the 8 inch pipes"), not a one-time setup. Same "future, not retroactive"
			// rule as idPrefixes: changing one never touches an element that already exists.
			// Values are null here and seeded by seedDefaultInputs() at init(), because the
			// unit-set-dependent ones go through niceDefault(), which reads the units strip out of the
			// DOM -- and `var settings = defaultSettings()` runs at module scope, before
			// DOMContentLoaded, where every lookup would silently fall back to SI.
			// NO reservoir head default, deliberately: reservoirHead() treats a blank head as "same
			// as the elevation" and keeps the two linked as the reservoir moves. Writing the same
			// number into head would look identical on screen while silently severing that link.
			// nodeElev covers junctions AND reservoirs: a from-scratch reservoir has no head until
			// the user gives it one -- no invisible driving head nobody entered.
			// **WHERE A NEW NODE'S ELEVATION COMES FROM** (Task 542): 'value' is the number in the
			// row beside it, 'dem' reads the land surface. Absent in a project saved before this
			// existed, and `|| 'value'` at every read makes that the correct old behaviour rather
			// than a migration.
			nodeElevSource: 'value',
			defaults: { nodeElev: null, demand: null, diameter: null, roughness: null, k: null,
				// Tank geometry (Task 248). Null here and filled by seedDefaultInputs(), same as
				// every other row -- which is also what migrates a document saved before tanks
				// existed, with no migration step of its own.
				tankLevel: null, tankMinLevel: null, tankMaxLevel: null, tankDiameter: null },
			// **STALE SINCE TASK 441, AND KEPT ON PURPOSE.** Nothing reads it: the Settings box does
			// not collapse anything (Tom: "No need ever to collapse"). It is still written so that a
			// project file saved before that day and one saved after have the same shape, exactly as
			// `fileAutosaveSeconds` was left. Drop it only with a storage version bump.
			sectionsOpen: { idPrefixes: false, defaults: true, mapDisplay: false, colors: false, computation: false, files: false },
			// SCREEN PIXELS since Task 331 -- see effectiveFontSize() for why map units went away.
			// 11 px is a legible small label at any zoom and means the same thing on every network
			// ever imported.
			// A DEFAULT ONLY REACHES A FIRST-TIME VISITOR: loadFromStorage() merges a saved settings
			// object ON TOP of these, so anyone who used the page earlier keeps their stored value.
			// That is why dev/lpn-spike/example-draw-fixture.js sets the size explicitly too.
			textSize: 11,
			// Junction dot DIAMETER in screen pixels; every other symbol is drawn against it.
			// 7 keeps a dot readable next to 11 px lettering without swallowing it.
			symbolSize: 7,
			// Pipe stroke in screen pixels, independent of both -- label, link and node size are
			// deliberately decoupled. 2 reads as a pipe rather than a hairline or a road.
			linkWidth: 2,
			symbolOpacity: 1, // 0-1, applied to symbols only (never labels) -- see refreshSymbolSizes()
			backdropOpacity: 1, // 0-1, applied to the backdrop image -- the other half of the same control
			// Draw a link's label ALONG its pipe, GIS-style, instead of horizontally beside it
			// (ROADMAP Task 329).
			alignPipeLabels: true,
			// **HOW FAR LEFT OF VERTICAL A LABEL MAY LEAN BEFORE IT TURNS 180 DEGREES**, in degrees.
			//
			// A label reads along a direction, and the reading direction may lean this many degrees
			// ANTICLOCKWISE of straight up before the label turns 180 degrees to stay readable. Up
			// always wins -- a near-vertical name reads bottom to top, as on every map.
			//
			// **"LEFT OF", NOT "PAST", AND NEVER A BARE ANGLE.** Stated as a CARTESIAN bearing
			// (counter-clockwise, y up) while the renderer works in SVG's frame -- y DOWN, the same
			// arithmetic CLOCKWISE -- the tolerance lands on the wrong side of vertical and every
			// near-vertical pipe reads top-to-bottom. "Degrees left of vertical" leaves no frame to
			// get wrong. A project carrying the old key gets this default.
			labelFlipLeftOfVertical: 20,
			// Draw the pale background patch behind every label (ROADMAP Task 330). ON, which is
			// what the page has always done and what keeps a label legible over a backdrop image --
			// the control exists because a clean drawing with no backdrop reads better without the
			// patches, which is a judgement about the sheet and therefore the user's to make.
			maskLabels: true,
			// **FLOW-DIRECTION ARROWS, ON** (Tom, 2026-09-01: "it would be nice to have a Settings
			// option to turn off flow direction arrows"). A switch that takes something away, so the
			// default is what the page has always drawn -- an upgrade must not restyle anyone's map.
			//
			// A VIEW PREFERENCE, and it lives in `settings` with maskLabels and alignPipeLabels
			// rather than in `doc`: an arrow is decoration on a result, not a property of the
			// network, so nothing in the model changes when it goes. `settings` is what
			// serializeProject() writes whole, which is exactly what a project TEMPLATE is for on
			// this page (there being no browser-level preference store here), and applySaved()
			// merges a saved object ON TOP of these defaults -- so a project saved before this key
			// existed comes back with arrows on, with no migration step.
			showArrows: true,
			// **THE LEADER ANGLE SNAP IS OFF UNTIL SOMEBODY ASKS FOR IT** (ROADMAP Task 408). Tom
			// asked for a snap that is the user's choice and never forced, and a feature that
			// arrives switched on has made the choice for them -- every existing drawing would have
			// its next label drag pulled somewhere the user did not put it. 0 is Off; 15, 30 and 45
			// are the increments he named. See EngCalcs.lpnGeom.snapLeaderOffset() for the magnet.
			leaderSnapDeg: 0,
			// One of LEGEND_POSITIONS' keys below. On a pointer the corner is the original hardcoded
			// CSS's, top right; **ON A PHONE THE TWO LEGENDS SWAP INTO THE TOP CORNERS** -- Tom,
			// 2026-08-25: "527 on phone, color legend upper right and label legend upper left."
			// See the colour key's own key below for why this is a DEFAULT and not an override.
			legendPosition: smallScreen() ? 'top-left' : 'top-right',
			// ---- colour by value (Task 384) ----
			// FLAT KEYS, not one nested `colors` object: applySaved() merges with a TOP-LEVEL
			// Object.assign and hand-lists the three nested objects it merges a level deeper, so a
			// fourth would come back from an older save missing every key added after it was written.
			// OFF by default. The base drawing is black linework on purpose, and colouring is a mode
			// the user enters, never the state they are handed.
			colorNodeField: '',   // '' = none, else a key of COLOR_NODE_FIELDS
			colorLinkField: '',   // '' = none, else a key of COLOR_LINK_FIELDS
			// **ONE COLOUR SCHEME PER ELEMENT CLASS, NOT ONE FOR THE MAP** (Tom, 2026-08-19:
			// "put a colour-ramp picker at the bottom of this group", said of BOTH symbology
			// groups). EPANET and epanet-js give nodes and links a scheme each, and a page that
			// already offers a field dropdown each was implying it. Nodes coloured by pressure and
			// links by velocity are two different questions on one sheet, and reading them in one
			// palette is what made the second one hard to see.
			//
			// A key of js/lpn-ramps.js's catalogue. **NOT the rainbow** -- Tom, 2026-08-18: it
			// "goes last, in its own group, and is never the default". Viridis is ordered,
			// perceptually uniform and readable by the ~8% of men who cannot separate the
			// rainbow's green/yellow/red end; every ramp the five-ramp era stored still opens.
			//
			// **A DOCUMENT WRITTEN WHEN THERE WAS ONE OF EACH OPENS UNCHANGED**: applySaved() gives
			// both groups the single value it finds, so nothing on the map changes colour.
			colorRampNode: 'viridis',
			colorRampLink: 'viridis',
			// HOW MANY CLASSES, 3 to 7 (Tom asked for "a choice of number of ranges"). Seven is
			// the default and the maximum: Brewer's own guidance is that a reader stops telling
			// classes apart somewhere around there. A document saved before this key existed is
			// held at the five bands it was drawn in -- see applySaved().
			//
			// PER GROUP for the same reason the ramp is -- see criterionClassCount().
			colorClassesNode: 7,
			colorClassesLink: 7,
			colorReverseNode: false,
			colorReverseLink: false,
			// Task 327's thematic map: colour is the whole message, so the GENERATED labels come
			// off. It never touches labelSettings, and it is one of three suppressors read by
			// applyLabelVisibility() -- see there. It does NOT hide the user's own Text (Task 428).
			colorThematic: false,
			// The colour key's own corner, separate from the labels legend's so the two do not
			// stack on top of each other. Opposite default corner for the same reason.
			//
			// **A DEFAULT, NEVER AN OVERRIDE.** applySaved() merges a stored settings object ON TOP
			// of this one (Object.assign(defaultSettings(), savedSettings)), so a project that
			// records a placement -- and every project does, settings being serialized whole --
			// opens in the corner it was saved in on any screen. Only a first-time visitor, and
			// Restore defaults, ever see the value below.
			colorLegendPosition: smallScreen() ? 'top-right' : 'bottom-right',
			// THE COLOUR BAND LIMITS, keyed 'node.pressure' / 'link.velocity', each an array of up
			// to six numbers IN THE DISPLAY UNIT. **ONE FIELD, WHOEVER PUT THE NUMBERS THERE** --
			// typed into the boxes, or written by pressing a classification method. Nothing records
			// which, because nothing needs to: Tom, 2026-08-19, of EPANET, *"one set of breaks, and
			// it's manual. But you can push a button to fill them using a method... The project
			// doesn't care where it came from other than 'I found it in the input box; I don't know
			// how it got there.'"*
			//
			// **A COMPUTED NUMBER IN HERE IS NOT THE UNIT-PARADIGM DEFECT, AND A SECOND FIELD TO KEEP IT
			// OUT WAS BUILT AND REJECTED (Task 448).** That rule stops us rewriting a user's numbers
			// silently and behind their back; pressing a method button is an explicit user action that
			// fills the boxes, exactly as typing in them is. Do not re-derive the two-field design.
			//
			// Empty/absent means "not filled in yet", and effectiveBreaks() fills it on the first read
			// that has a real range to classify. From then on the numbers are STATIC: an animation's
			// colours keep their meaning from frame to frame, which is the whole reason they are stored
			// rather than recomputed. A whole saved object replacing this one is correct -- a missing
			// field reads as not-filled-in, so it needs no per-key merge.
			colorBreaks: {},
			// WHICH RANGE ALLOCATION MODE each coloured field is on, keyed the same way -- a mode is a
			// claim about one quantity's distribution, and pressure and velocity do not share one.
			// Absent means 'equal'. 'manual' is stored here like any other and means the numbers in the
			// boxes are the user's own: touching a limit field writes it. Replaced wholesale by a save
			// for the same reason colorBreaks is.
			colorModes: {}
			// A save may still carry keys since removed (`fileAutosaveSeconds`, `mapHeight`).
			// applySaved() merges the save ONTO these defaults, so a stale key rides along unread.
		};
	}
	var settings = defaultSettings();
	// Fills any null in settings.defaults with its real starting value. Called from init() (after
	// the units strip exists, so niceDefault() can see it) and again after Restore defaults. Only
	// nulls are touched, so it doubles as the forward-migration for a save written before a given
	// default existed -- the merge in loadFromStorage() leaves such a key null and this fills it.
	function seedDefaultInputs() {
		var d = settings.defaults;
		function fill(key, value) { if (d[key] === null || d[key] === undefined) { d[key] = value; } }
		fill('nodeElev', 0);
		fill('demand', 0);
		fill('diameter', niceDefault('lpn_u_diameter', 'in', 4, 0.1));
		fill('roughness', 100);
		fill('k', 2);
		// A TANK'S FOUR NUMBERS ARE ALL VERTICAL DISTANCES IN THE ELEVATION/HEAD UNIT, the vessel
		// diameter included -- EPANET's own convention, and the one that catches people out, since
		// a PIPE diameter two rows up is in inches or millimetres. The numbers describe an ordinary
		// municipal storage tank, roughly 15 m across and 9 m tall, about two-thirds full.
		fill('tankLevel', niceDefault('lpn_u_elevhead', 'fth2o', 20, 6));
		fill('tankMinLevel', 0);
		fill('tankMaxLevel', niceDefault('lpn_u_elevhead', 'fth2o', 30, 9));
		fill('tankDiameter', niceDefault('lpn_u_elevhead', 'fth2o', 50, 15));
	}

	// User-supplied backdrop image. Deliberately NOT part of `doc`/the undo-snapshotted document:
	// saveUndoSnapshot() deep-clones doc via JSON.parse(JSON.stringify(doc)) on every discrete
	// mutation and keeps up to 20 snapshots -- a multi-hundred-KB-to-multi-MB embedded data URI in
	// there would multiply badly. Still persisted to localStorage as a sibling key.
