	function syncNewBoxPlace() {
		var box = document.getElementById('lpn_new_place'), geo = newBoxIsGeo();
		if (!box) { return; }
		box.disabled = !geo;
		if (!geo) { box.value = ''; }
	}
	function closeNewBox() {
		var box = newBoxEl();
		hidePanel(box);
	}
	// **THE ANSWERS ARE A VALUE, AND MAKING THE PROJECT IS A FUNCTION OF IT.** Reading the box and
