	// shape and are read by the same code (curvePointTable), so they are one list here.
	function libCurves() {
		return doc.links.filter(function (l) {
			return (l.type === 'pump' || (l.type === 'valve' && (l.valveType || '').toUpperCase() === 'GPV'))
				&& !l.curveRef;
		});
	}
